    if (ch == '(') {
      depth++;
      if (depth == 1) {
        counts.add(0); // Start counting at the topmost level
      }
    } else if (ch == ')') {
      if (depth > 0) {
        depth--;
        counts[counts.length - 1]++; // Increment the current level's count
      }
    }
  }

  return counts;
}

