import 'dart:math';

List<int> parseNestedParens(String parenString) {
  final List<int> result = [];
  int depth = 0;

  for (var i = 0; i < parenString.length; i++) {
    if (parenString[i] == '(') {
      depth++;
    } else if (parenString[i] == ')') {
      depth--;
    }

    // Check if we're at the end of a nested level, but not after closing all brackets.
    if (depth <= 0 && i + 1 < parenString.length) {
      continue;
    }

    // If current character is a digit and either it's the first char or previous was non-digit,
    // then record as start of number. Otherwise, just add to current number.
    bool isNewNumber = false;
    if (i == 0 || !RegExp(r'[0-9]').hasMatch(parenString[i - 1])) {
      isNewNumber = true;
    }

    if (isNewNumber && RegExp(r'\\d').hasMatch(parenString[i])) {
      var numStartIndex = i;

      while (i < parenString.length && RegExp(r'\d').hasMatch(parenString[i])) {
        i++;
      }

      String? numStr = parenString.substring(numStartIndex, i);
      if (numStr != null && numStr.isNotEmpty) {
        try {
          int value = int.parse(numStr);
          result.add(value);
        } catch (_) {}
      }
    }
  }

  return result;
}
