class Node {
  final String name;
  final Map<String, dynamic>? data;
  late final List<Node> children;
  late final bool isLeaf;

  Node(this.name, this.data, {required this.children}) : isLeaf = children.isEmpty;

  factory Node.fromJson(Map<String, dynamic> json) {
    var _data = json['data'] as Map<String, dynamic>?;
    var _children = (json['children'] as List<dynamic>)
        .map((childJson) => Node.fromJson(childJson))
        .toList();

    return Node(json['name'], _data, children: _children);
  }

  static List<Node> fromJsonList(List<dynamic> jsonArray) {
    return jsonArray.map((item) => Node.fromJson(item)).toList();
  }

  @override
  String toString() {
    return '{Name: $name, Data: ${data != null ? jsonEncode(data!) : "null"}, Children: [${children.join(', ')}]}';
  }
}

