// 2. A set called [uniqueChars] is used to store unique character code units.
// 3. Each character in the string is processed by converting it into its Unicode code unit using `.codeUnits.first`.
// 4. These code units are added to the set which automatically handles uniqueness.
// 5. Finally, the size of the set is returned, indicating how many distinct characters were found.

int countDistinctCharacters(String string) {
  // Handle edge case where input is null or empty
  if (string == null || string.isEmpty) return 0;

  // Use a set to track unique character code units
  final Set<int> uniqueChars = <int>{};

  // Process each character and add their code units to the set
  for (final String char in string.split('')) {
    final int codeUnit = char.codeUnits.first;
    uniqueChars.add(codeUnit);
  }

  // Return the count of unique characters
  return uniqueChars.length;
}
