// Helper function to find the maximum proper divisor of a number.
int largestDivisor(int n) {
  // Initialize the maximum divisor as -1 to indicate no valid divisor found yet.
  int max = -1;

  // Loop through all possible divisors from 2 up to the square root of n.
  for (var i = 2; i <= sqrt(n); ++i) {
    // Check if i is a divisor of n.
    if (n % i == 0) {
      final other = n ~/ i; // The corresponding pair factor.

      // Update the maximum with either the smaller or larger divisor,
      // ensuring they are both less than n (proper divisors).
      max = max(max, min(i, other));
      max = max(max, max(i, other));
    }
  }

  // Return the maximum proper divisor found. If none found, returns -1.
  return max;
}
