bool isPrime(int num) {
  if (num <= 1) return false;
  if (num == 2) return true;
  if (num % 2 == 0) return false;

  int sqrtNum = sqrt(num).toInt();
  for (int i = 3; i <= sqrtNum; i += 2) {
    if (num % i == 0) return false;
  }

  return true;
}

int fibonacci(int n) {
  if (n <= 1) return n;

  var a = 0, b = 1;
  for (var i = 2; i <= n; i++) {
    var c = a + b;
    a = b;
    b = c;
  }
  return b;
}
