bool isPrime(int num) {
  if (num <= 1) return false;
  if (num == 2 || num == 3) return true;
  if (num % 2 == 0) return false;

  var d = num - 1;
  var s = 0;

  while (d % 2 == 0) {
    d ~/= 2;
    s += 1;
  }

  List<int> witnesses = [2, 3, 5, 7];

  for (var witness in witnesses) {
    if (witness >= num) continue;

    var x = pow(witness, d, num);

    if (x == 1 || x == num - 1) continue;

    for (var _ in 0..s-1) {
      x = pow(x, 2, num);

      if (x == num - 1) break;
    }

    if (x != num - 1) {
      return false;
    }
  }

  return true;
}

