bool isPalindrome(String text) {
  if (text.isEmpty) return true;

  int left = 0, right = text.length - 1;
  while (left < right) {
    final lChar = text[left];
    final rChar = text[right];

    // Skip non-alphanumeric characters and convert to lowercase
    if (!lChar.isLetterOrDigit && !rChar.isLetterOrDigit) {
      left++;
      right--;
      continue;
    }

    if (!lChar.isLetterOrDigit || !rChar.isLetterOrDigit) {
      if (!lChar.isLetterOrDigit) left++;
      if (!rChar.isLetterOrDigit) right--;
      continue;
    }

    if (lChar.toLowerCase() != rChar.toLowerCase()) {
      return false;
    }

    left++;
    right--;
  }

  return true;
}
