// Function to check if two strings contain the same characters with the same counts
bool sameChars(String s0, String s1) {
  // If lengths are different, they can't be anagrams
  if (s0.length != s1.length) {
    return false;
  }

  // Create frequency maps for both strings
  Map<String, int> freqMapS0 = _getFrequencyMap(s0);
  Map<String, int> freqMapS1 = _getFrequencyMap(s1);

  // Compare the frequency maps
  return freqMapS0 == freqMapS1;
}

// Helper function to create a frequency map of characters in a string
Map<String, int> _getFrequencyMap(String str) {
  Map<String, int> frequencyMap = {};

  for (String char in str.split('')) {
    frequencyMap[char] = (frequencyMap.containsKey(char)
        ? frequencyMap[char]!
        : 0) + 1;
  }

  return frequencyMap;
}
