  // Check if the number of fruits is less than or equal to zero
  if (fruits.length <= 0 || n < 1) {
    return 0;
  }

  // Count how many times each fruit appears in the string
  Map<String, int> countMap = {};
  for (String fruit in fruits) {
    if (countMap.containsKey(fruit)) {
      countMap[fruit] = countMap[fruit]! + 1;
    } else {
      countMap[fruit] = 1;
    }
  }

  // Calculate the total possible combinations of fruits based on counts and available quantity 'n'
  int totalCombinations = 0;
  for (var entry in countMap.entries) {
    String fruitType = entry.key;
    int fruitCount = entry.value;

    // If there are more instances of this type than available, use only what's available
    int maxPossible = min(fruitCount, n);

    // Add all permutations from 0 up to the maximum possible
    for (int i = 0; i <= maxPossible; ++i) {
      totalCombinations += combination(n - i, i);
    }
  }

  return totalCombinations;
}

// Helper function to calculate combination: C(n, k)
int combination(int n, int k) {
  if (k > n) return 0;
  if (k == 0 || k == n) return 1;
  if (k == 1) return n;

  k = min(k, n - k); // Take advantage of symmetry

  var result = 1;
  for (int i = 1; i <= k; ++i) {
    result *= (n - i + 1);
    result ~/= i;
  }
  return result;
}
