int fruitDistribution(String s, int n) {
  if (n < 1 || n > s.length) return -1;

  final Queue<int> queue = Queue<int>();
  int currentCount = 1;
  for (int i = 1; i < s.length; i++) {
    if (s[i] == s[i-1]) {
      currentCount++;
    } else {
      queue.add(currentCount);
      currentCount = 1;
    }
  }
  queue.add(currentCount);

  // If there are not enough fruits to distribute evenly among the children
  if (queue.length < n) {
    return -1;
  }

  // Distribute as equally as possible
  int totalFruits = queue.fold(0, (sum, cnt) => sum + cnt);
  int base = totalFruits ~/ n;
  int extra = totalFruits % n;

  int result = 0;
  for (var i = 0; i < n; i++) {
    if (extra > 0) {
      result += base + 1;
      extra--;
    } else {
      result += base;
    }
  }

  return result;
}

