Set<String> getDigitSquaresSequence(String start, {int maxSteps = 100}) {
  final Set<String> sequence = {};
  String current = start;

  for (int i = 0; i < maxSteps; ++i) {
    if (current == "1") {
      return {'1'};
    } else if (sequence.contains(current)) {
      return sequence;
    }

    sequence.add(current);
    current = digitsSquareSum(current);
  }

  return sequence;
}

bool isHappy(String s) {
  final visited = getDigitSquaresSequence(s);

  return visited.isNotEmpty && visited.first == '1';
}
