  // If k is zero or equal to n, the result is 1
  if (k == 0 || k == n) {
    return 1;
  }

  // Use symmetry property C(n, k) = C(n, n-k) for efficiency
  if (k > n - k) {
    k = n - k;
  }

  // Calculate the product iteratively
  int result = 1;
  for (int i = 1; i <= k; i++) {
    result *= (n - i + 1);
    result ~/= i;
  }

  return result;
}

