int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  if (cols == 0) return 0;

  // Initialize the DP table
  List<List<int>> dp = List.generate(rows + 1, (_) => List.filled(cols + 1, 0));

  for (int i = 1; i <= rows; i++) {
    for (int j = 1; j <= cols; j++) {
      // If current cell is a well
      if (grid[i - 1][j - 1] > 0) {
        // Calculate how much water we can carry from this well to fill others
        int neededWater = grid[i - 1][j - 1];
        int availableCarry = min(neededWater, capacity);

        // Check left and up directions to see if there's more water that needs filling
        // We want to maximize the amount of filled wells by carrying as much as possible

        // Try moving right with remaining capacity after this well
        var option1 = 0;
        int c = availableCarry;
        while (j < cols && c > 0) {
          if (grid[i - 1][j] > 0) {
            option1 += min(grid[i - 1][j], c); 
            c -= min(grid[i - 1][j], c);
          }
          j++;
