            option2 += min(grid[i][j - 1], c);
            c -= min(grid[i][j - 1], c);
          }
          i++;
        }

        // Choose the best direction to move next
        int takeMax = max(option1, option2);

        // Fill the current well fully or partially based on what we could carry
        // The value stored in dp[i][j] will be the maximum number of wells we've filled so far along the path
        dp[i][j] = dp[i-1][j-1] + min(availableCarry, grid[i-1][j-1]) + takeMax;
