    for (var j = colIndex + 1; j < cols; ++j) {
      if (grid[rowIndex][j] > maxVal) {
        maxVal = grid[rowIndex][j];
        indexInRow = j;
        break;
      }
    }

    if (maxVal != -1 || j < cols) {
      pq.add(QueueElement(maxVal, rowIndex, indexInRow));
    }
  }

  return result;
