class QueueElement implements Comparable<QueueElement> {
  final int value;
  final int rowIndex;
  final int colIndex;

  QueueElement(this.value, this.rowIndex, this.colIndex);

  @override
  int compareTo(QueueElement other) {
    return value.compareTo(other.value);
  }
