int maxFill(List<List<int>> grid, int capacity) {
  if (grid == null || grid.isEmpty || grid[0].isEmpty) return 0;

  final rows = grid.length;
  final cols = grid[0].length;

  // Initialize the result matrix with -1 for unvisited cells and track the maximum fill count
  final res = List.generate(rows, (_) => List.filled(cols, -1));
  var maxCount = 0;

  void dfs(int row, int col, int currentCapacity) {
    if (row < 0 || row >= rows || col < 0 || col >= cols) return; // Out of bounds
    if (res[row][col] != -1) return; // Already visited or processed
    if (currentCapacity <= 0) return; // No more capacity left

    if (grid[row][col] > 0 && grid[row][col] <= capacity) { 
      // If cell has value between 1 to capacity, we can use it
      int val = grid[row][col];

      // Try filling this cell at full capacity first
      if (val == capacity) {
        res[row][col] = val;
        maxCount = max(maxCount, val);

        // Check adjacent cells
        dfs(row + 1, col, currentCapacity - val); // Down
        dfs(row - 1, col, currentCapacity - val); // Up
        dfs(row, col + 1, currentCapacity - val); // Right
        dfs(row, col - 1, currentCapacity - val); // Left

        res[row][col] = -1; // Reset after backtracking
        return;
      }

      // Otherwise try all possible splits from 1 to remaining capacity
      for (var i = 1; i <= min(val, currentCapacity); i++) {
        res[row][col] = i;
        dfs(row + 1, col, currentCapacity - i); // Down
        dfs(row - 1, col, currentCapacity - i); // Up
        dfs(row, col + 1, currentCapacity - i); // Right
        dfs(row, col - 1, currentCapacity - i); // Left

        // Backtrack
        res[row][col] = -1;
      }
    } else {
      // If cell is 0, just move on
      dfs(row + 1, col, currentCapacity);
      dfs(row - 1, col, currentCapacity);
      dfs(row, col + 1, currentCapacity);
      dfs(row, col - 1, currentCapacity);
    }
  }

  for (var r = 0; r < rows; r++) {
    for (var c = 0; c < cols; c++) {
      dfs(r, c, capacity);
    }
  }

  return maxCount;
}
