The solution uses depth-first search (DFS) to explore all possibilities. The key idea is that each time a non-zero cell is encountered, we attempt to place as much water as possible in that cell up to its capacity. We then recursively check the neighboring cells with reduced available capacity.

Here's how it works:

- For each cell in the grid:
   - If the cell contains some positive number less than the current capacity, we consider placing different amounts in it.
   - When placing a certain amount, we update our answer and proceed to explore the rest of the grid with updated capacity.
   - After exploring, we backtrack by resetting the cell value.
   - If the cell is zero, we simply continue to neighboring cells without changing the capacity

import 'dart:math';

int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  if (cols == 0) return 0;

  // Directions for moving in the four directions
  const dirs = <List<int>>[
    [1, 0],   // down
    [-1, 0],  // up
    [0, 1],   // right
    [0, -1]   // left
  ];

  bool isVisited(int r, int c, List<List<bool>> visited) {
    return r >= 0 && r < rows && c >= 0 && c < cols && !visited[r][c];
  }

  void dfs(int row, int col, List<List<bool>> visited, int currentCapacity,
      int& maxVal) {
    if (!isVisited(row, col, visited)) return;

    visited[row][col] = true;

    if (grid[row][col] > 0) {
      currentCapacity -= grid[row][col];
    }

    if (currentCapacity < 0) return;

    maxVal = max(maxVal, currentCapacity);

    for (var dir in dirs) {
      final newRow = row + dir[0];
      final newCol = col + dir[1];
      dfs(newRow, newCol, visited, currentCapacity, maxVal);
    }
  }

  int result = 0;
  for (int i = 0; i < rows; ++i) {
    for (int j = 0; j < cols; ++j) {
      List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));
      int currentMax = 0;
      dfs(i, j, visited, capacity, currentMax);
      result = max(result, currentMax);
    }
  }

  return result;
}

