List<int> maximum(List<int> arr, int k) {
  final n = arr.length;
  if (n == 0 || k <= 0 || k > n) return [];

  // Initialize the deque data structure to store indices of elements in a sliding window.
  Deque<int> dq = LinkedDeque();

  // Process each element in the array.
  for (var i = 0; i < n; i++) {
    // Remove all elements smaller than current element from the back of deque.
    while (!dq.isEmpty && arr[dq.back!] <= arr[i]) {
      dq.removeLast();
    }

    // Add current index to deque.
    dq.addLast(i);

    // Check if front of deque is out of bounds of current window.
    while (dq.front! < i - k + 1) {
      dq.removeFirst();
    }

    // Once we have processed at least k elements, start adding results.
    if (i >= k - 1) {
      result.add(arr[dq.front!]);
    }
  }

  return result;
}

// Helper class for deque implementation using linked list.
class Deque<T> extends LinkedList<T> {
  bool get isEmpty => length == 0;

  void removeLast() {
    super.removeLast();
  }

  void addLast(T value) {
    super.add(value);
  }

  void removeFirst() {
    super.removeFirst();
  }

  T? get back => last;
  T? get front => first;
}

extension LinkedListExtension<T> on LinkedList<T> {
  void add(T value) {
    super.addLast(value);
  }
}
