List<int> maximum(List<int> arr, int k) {
  if (k == 0 || arr.isEmpty) return [];

  final n = arr.length;
  if (n <= k) {
    List<int> result = List.from(arr);
    result.sort((a, b) => b.compareTo(a));
    return result;
  }

  // Sliding window to find the max in each window of size k
  final res = <int>[];
  for (int i = 0; i <= n - k; ++i) {
    var currentMax = arr[i];
    for (int j = i + 1; j < i + k; ++j) {
      currentMax = max(currentMax, arr[j]);
    }
    res.add(currentMax);
  }

  // Sort and return the top k elements from the results
  res.sort((a, b) => b.compareTo(a));
  return res.take(k).toList();
}
