import 'dart:math';

int canArrange(List<int> arr) {
  if (arr.isEmpty || arr.length == 1) return 0;

  int evenCount = 0, oddCount = 0;
  for (var num in arr) {
    if (num % 2 == 0) evenCount++;
    else oddCount++;
  }

  // Check if all elements are the same parity
  if (evenCount == arr.length || oddCount == arr.length) return 0;

  // Check if there's at least one pair of consecutive numbers with different parities
  bool hasMixedParityPair = false;
  for (int i = 0; i < arr.length - 1; i++) {
    if ((arr[i] % 2 != arr[i + 1] % 2)) {
      hasMixedParityPair = true;
      break;
    }
  }

  if (!hasMixedParityPair && arr.length > 2) return 0;

  // Special case when length is 2 and they have different parities
  if (arr.length == 2 && (arr[0] % 2 != arr[1] % 2)) return 1;

  // For longer arrays, check if we can arrange by swapping two mismatched pairs
  List<int> sortedArr = [...arr];
  sortedArr.sort((a, b) => a.compareTo(b));
  for (int i = 0; i < sortedArr.length - 1; i++) {
    if ((sortedArr[i] % 2 != sortedArr[i + 1] % 2)) {
      // Find matching number to swap with
      for (int j = i + 1; j < sortedArr.length; j++) {
        if ((sortedArr[j] % 2 == sortedArr[i] % 2) &&
            (sortedArr[j+1] % 2 == sortedArr[i+1] % 2)) {
          // Swap them
          int temp = sortedArr[i];
          sortedArr[i] = sortedArr[j];
          sortedArr[j] = temp;

          // Now check if this arrangement works
          bool valid = true;
          for (int k = 0; k < sortedArr.length - 1; k++) {
            if ((sortedArr[k] % 2 == sortedArr[k+1] % 2)) {
              valid = false;
              break;
            }
          }

          if (valid) return 1;
        }
      }
    }
  }

  return 0;
}
