String fileNameCheck(String fileName) {
  if (fileName.isEmpty || !File(fileName).existsSync()) {
    return "invalid";
  }

  final file = File(fileName);
  if (!file.existsSync()) {
    return "not found";
  }

  // Check for invalid characters in the filename.
  const forbiddenChars = {r'\\', '/', ':', '*', '?', '"', '<', '>', '|'};
  for (final c in fileName.split('').where((c) => c.isNotEmpty)) {
    if (forbiddenChars.contains(c)) {
      return "contains illegal character(s)";
    }
  }

  // Ensure that the name is not too long. Windows has a max path length of 260.
  if (fileName.length > 255) {
    return "too long";
  }

  final extIndex = fileName.lastIndexOf('.');
  String extension;
  if (extIndex != -1 && extIndex < fileName.length - 1) {
    extension = fileName.substring(extIndex + 1);
    if (extension.length >= 3) {
      final validExtensions = {'txt', 'log', 'csv', 'json', 'xml', 'html', 
                           'css', 'js', 'md', 'yml', 'yaml', 'sql',
                           'jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp', 'svg'}; 

      if (!validExtensions.contains(extension.toLowerCase())) {
        return "unsupported format";
      }
    } else {
      return "invalid extension";
    }
  } else {
    // No extension, but it's okay to have no extension as well
    return "ok";
  }
}
