  } else if (ext == 'png' || ext == 'jpg' || ext == 'jpeg' || ext == 'gif') {
    return "Image file";
  } else if (ext == 'mp3' || ext == 'wav' || ext == 'aac') {
    return "Audio file";
  } else if (ext == 'mp4' || ext == 'avi' || ext == 'mkv') {
    return "Video file";
  } else if (ext == 'zip' || ext == 'rar' || ext == '7z') {
    return "Archive file";
  } else if (ext == 'pdf' || ext == 'docx' || ext == 'xlsx' || ext == 'pptx') {
    return "Document file";
  } else if (ext == 'css' || ext == 'js' || ext == 'html') {
    return "Web development file";
  } else if (ext == 'py' || ext == 'java' || ext == 'cpp' || ext == 'c') {
