  if (parts.length < 2) return "Invalid file name";

  String extension = parts.last;
  String baseName = fileName.substring(0, fileName.lastIndexOf("."));

  // Check for valid characters in the base name
  if (!RegExp(r'^[a-zA-Z0-9_\-]+$').hasMatch(baseName)) {
    return "Invalid characters in filename: $fileName. Only alphanumeric and underscores are allowed.";
  }

  // Validate extensions by checking against a list of known extensions
  const Set<String> validExtensions = {
    'txt', 'pdf', 'docx', 'xlsx', 'pptx',
    'jpg', 'jpeg', 'png', 'gif', 'bmp',
    'mp3', 'wav', 'ogg', 'aac', 'flac',
    'avi', 'mkv', 'mov', 'mpeg', 'wmv'
  };

  if (!validExtensions.contains(extension.toLowerCase())) {
    return "Unsupported extension: $extension. Valid extensions include: ${validExtensions.join(", ")}";
  }

  return "Valid file name!";
