String fileNameCheck(String fileName) {
  if (fileName == null || fileName.isEmpty) return 'Invalid file name: empty';

  final parts = fileName.split('.');
  if (parts.length < 2) return 'Invalid file name: no extension';

  String baseName;
  List<String> extensions;

  if (parts[0].isEmpty) {
    // No base name, only extensions
    if (parts.length > 1 && parts.last.isNotEmpty) {
      baseName = '';
      extensions = parts.toList();
    } else {
      return 'Invalid file name: invalid format';
    }
  } else if (parts[0] != '') {
    baseName = parts[0];
    extensions = parts.sublist(1);
  } else {
    return 'Invalid file name: invalid format';
  }

  if (extensions.any((e) => e.isEmpty)) {
    return 'Invalid file name: contains empty extension';
  }

  if (!extensions.every((e) => isAlphaNumeric(e))) {
    return 'Invalid file name: contains non-alphanumeric characters in extensions';
  }

  var hasValidExtension =
      extensions.contains('txt') ||
          extensions.contains('log') ||
          extensions.contains('csv');

  if (!hasValidExtension) {
    return 'Invalid file name: invalid extension(s)';
  }

  if (baseName.trim().isNotEmpty && !isAlphaNumeric(baseName)) {
    return 'Invalid file name: invalid characters in base name';
  }

  return 'Valid file name: $fileName';
}

bool isAlphaNumeric(String s) {
  for (var c in s.codeUnits) {
    if ((c < 'A' || c > 'Z') && (c < 'a' || c > 'z')) {
      if (c < '0' || c > '9') {
        return false;
      }
    }
  }
  return true;
}

