// This function checks whether a given filename follows certain rules:
//
// - Contains only alphanumeric characters, underscores (_), hyphens (-),
//   and periods (.)
// - Does not start with a period or underscore
// - Has at least one character in it
// - Is no longer than 256 characters long
//
// It returns "Valid" if all those conditions are met. Otherwise, it returns
// "Invalid".
String fileNameCheck(String fileName) {
  // First check that we have something to work with...
  if (fileName.isEmpty || fileName.length > 256) {
    return "Invalid";
  }

  final firstChar = fileName[0];
  if (firstChar == '.' || firstChar == '_') {
    return "Invalid";
  }

  // We don't need to check for special characters anymore since we're using a regex,
  // but let's keep the same restrictions as before
  final pattern = r'^[^._][A-Za-z0-9_.-]*$';
  final regExp = RegExp(pattern);

  return regExp.hasMatch(fileName)
      ? "Valid"
      : "Invalid";
}
