int getMaxTriples(int n) {
  if (n < 3) return 0;

  int max = 0;
  for (var i = 1; i <= n / 3; ++i) {
    var jMax = (n - i * 3) ~/ 2;
    // For each i, find the maximum possible j such that i + j*2 ≤ n
    max += min(i, jMax);
  }
  return max;
}
