int getMaxTriples(int n) {
  int max = -1;

  for (var a = 3; a <= n; a++) {
    if (a % 2 == 0 && a >= 6) {
      var bStart = ((a * a) / 4).toInt();
      if (bStart > n) break;

      // Check for all possible B values from bStart to n, step by 2
      for (var b = bStart; b <= n; b += 2) {
        // Calculate c using the formula derived from Pythagorean triple conditions
        double cSquare = pow(a, 2) + pow(b, 2);

        // Ensure that c is integer and within range
        if (!isPerfectSquare(cSquare)) continue;
        var c = sqrt(cSquare).toInt();

        if (c > n || c < 1) continue;

        // Increment count of valid triples found
        max++;
      }
    } else {
      // For odd a, find matching even numbers with specific pattern
      var bStart = ((a * a) / 4).toInt() + 1;
