import 'dart:collection' show LinkedHashSet;

// Helper function to generate all permutations of a string
List<String> getPermutations(String input) {
  List<List<int>> indices = [];
  List<String> chars = input.split('').toList();

  for (var i in Range(0, input.length - 1)) {
    var row = [i];
    indices.add(row);
  }

  while (indices.isNotEmpty) {
    var lastRow = indices.last;
    var lastIndex = lastRow.last;
    var nextIndex = lastIndex + 1;

    if (nextIndex >= input.length) {
      var prevRow = indices.removeLast();
      var prevRowLastVal = prevRow.last;

      var newIndices = [...prevRow];
      newIndices.removeAt(prevRow.indexOf(prevRowLastVal));
      newIndices.addAll(indices.lastWhere((row) => row.first != prevRowLastVal).last);

      indices.add(newIndices);
    } else {
      indices[lastRow.length - 1].add(nextIndex);
    }
  }

  Set<LinkedHashSet<int>> uniqueCombinations = {};
  for (var combination in combinations) {
    var sortedCombination = combination.toList()..sort();
    uniqueCombinations.add(LinkedHashSet.from(sortedCombination));
  }

  var result = [] as List<String>;
  for (var indexSet in uniqueCombinations) {
    var permutation = [];
    for (var i in indexSet) {
      permutation.add(chars.elementAt(i));
    }
    result.add(permutation.join(''));
  }

  return result;
}

List<Iterable> combinations(Iterable iterable) sync* {
  final length = iterable.length;

  if (length == 0) yield const [];

  yield* _combinations(iterable, length);

  void _combinations<T>(T element, int n) sync* {
    if (n == 0) yield [];
    for (int i = 0; i <= element.length; i++) {
      T subset = element.skip(i).take(element.length - i).toList(); 
      yield* _combinations(subset, n - 1);
    }
  }
}
