import 'dart:math';

String findMax(List<String> words) {
  if (words.isEmpty) return "";

  int maxIndex = 0;
  for (int i = 1; i < words.length; i++) {
    if (_calculateScore(words[i]) > _calculateScore(words[maxIndex])) {
      maxIndex = i;
    }
  }
  return words[maxIndex];
}

int _calculateScore(String word) {
  List<int> letters = [];
  int sum = 0;
  int count = 0;
  for (var c in word.split('')) {
    var letter = c.toUpperCase();
    if ('A' <= letter && letter <= 'Z') {
      letters.add(letter.codeUnitAt(0) - 'A'.codeUnitAt(0));
    } else {
      letters.add(-1);
    }
  }
  for (int i = 0; i < letters.length; i++) {
    if (letters[i] != -1) {
      sum += letters[i] + 1;
      count++;
    }
  }
  return sum / (count.toDouble() * sqrt(count.toDouble()));
}
